import React, { useState, useMemo, useEffect } from 'react';
import { LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, ReferenceArea, Label } from 'recharts';
import { Users, Pill, Activity, ArrowLeft, AlertCircle, Calendar, ChevronDown, Search, X, Database, AlertTriangle, HeartPulse, Shuffle, Building2, Loader2, ClipboardCheck } from 'lucide-react';
import './index.css';

// --- 靜態與模擬數據 ---
const admissionHistory = [{ id: 'ADM-001', date: '2026/09/10 - 09/30 (本次住院)' }];
const fullData = Array.from({ length: 21 }, (_, i) => ({ date: '09/' + (10 + i), na: 142 - (i * 0.8) + Math.sin(i), k: 3.6 + (i * 0.12), index: i }));
const medData = [{ name: 'FUROSEMIDE', type: 'Na+', startIdx: 0, endIdx: 15, color: '#3B82F6', impact: '138 -> 128', level: '高度相關' }];
const mockPatients = [
  {id:'P001', name:'王小明', info:'(男/68)', na:'128', k:'4.5', room:'802-1', status:'危急'}, 
  {id:'P002', name:'李大同', info:'(男/72)', na:'138', k:'4.2', room:'805-2', status:'觀察中'}
];

// 你原本前端定義的分類清單 (避免呼叫不存在的 API)
const categories = [
    "Cardiovascular", "Dermatologic", "Endocrine & metabolic",
    "Gastrointestinal", "Genitourinary", "Hematologic & oncologic",
    "Hepatic", "Local", "Nervous system", "Neuromuscular & skeletal",
    "Respiratory", "Otic", "Renal", "Hypersensitivity", "Immunologic",
    "Psychiatric", "Musculoskeletal", "Ophthalmic", "Miscellaneous"
];

export default function App() {
  const [view, setView] = useState('overview');
  const [selectedPatient, setSelectedPatient] = useState(null);
  const [windowSize, setWindowSize] = useState(7);
  const [startIndex, setStartIndex] = useState(0);

  // --- 藥物搜尋專用狀態 ---
  const [searchQuery, setSearchQuery] = useState('');
  const [hasResults, setHasResults] = useState(false);
  const [showCategories, setShowCategories] = useState(false);
  const [currentLabel, setCurrentLabel] = useState('所有藥物列表');

  const [searchResults, setSearchResults] = useState([]);
  const [isLoading, setIsLoading] = useState(false);
  const [stats, setStats] = useState({ total: 0, with_reactions: 0 });
  const [selectedCategory, setSelectedCategory] = useState('');
  const [selectedDrug, setSelectedDrug] = useState(null);

  const visibleData = useMemo(() => fullData.slice(startIndex, startIndex + windowSize), [startIndex, windowSize]);

  // 載入統計數據 (對應你 app.py 的 /api/stats)
  useEffect(() => {
    if (view === 'repository') {
      fetch('http://localhost:5000/api/stats')
        .then(res => {
           if(!res.ok) throw new Error("API 回應錯誤");
           return res.json();
        })
        .then(data => setStats(data))
        .catch(err => console.error("無法載入統計(請確認 Flask 是否啟動):", err));
    }
  }, [view]);

  // 核心搜尋 API (對應你 app.py 的 /api/search)
  const performSearch = async (params, labelText) => {
    setIsLoading(true);
    setHasResults(true);
    setCurrentLabel(labelText);

    try {
      const queryParams = new URLSearchParams();
      if (params.keyword) queryParams.append('keyword', params.keyword);
      if (params.filter) queryParams.append('filter', params.filter);
      if (params.category) queryParams.append('category', params.category);
      queryParams.append('page', 1);
      queryParams.append('page_size', 2000);

      const response = await fetch("http://localhost:5000/api/search?" + queryParams.toString());
      if (!response.ok) throw new Error("網路請求失敗");

      const json = await response.json();
      // 你的 app.py 會把結果包在 json.data 裡
      setSearchResults(json.data || []);
    } catch (error) {
      console.error("搜尋發生錯誤:", error);
      alert("無法連線到資料庫！請確認 Flask (app.py) 是否已啟動於 Port 5000。");
      setHasResults(false);
    } finally {
      setIsLoading(false);
    }
  };

  const handleSearchAll = () => {
    setSearchQuery(''); setSelectedCategory('');
    performSearch({ keyword: '' }, '完整收錄藥物');
  };

  const handleSearchReactions = () => {
    setSearchQuery(''); setSelectedCategory('');
    performSearch({ filter: 'reactions' }, '含不良反應資料庫');
  };

  const handleCategoryClick = (cat) => {
    setSearchQuery(''); setShowCategories(false);
    setSelectedCategory(cat);
    performSearch({ category: cat }, "分類：" + cat);
  };

  const handleTextSearch = () => {
    if (!searchQuery.trim()) return;
    setSelectedCategory('');
    performSearch({ keyword: searchQuery.trim() }, "搜尋：" + searchQuery);
  };

  // --- 1. 藥物查詢 (Repository) 視圖 ---
  if (view === 'repository') {
    const repoContainerClass = "w-full flex flex-col items-center transition-all duration-500 ease-in-out " + (hasResults ? "pt-8 pb-6 border-b border-slate-200 bg-white sticky top-0 z-50 shadow-sm" : "pt-[20vh]");
    const logoContainerClass = "text-center transition-all duration-500 " + (hasResults ? "mb-4 flex items-center gap-3" : "mb-8");
    const logoTextClass = "font-bold text-[#0f4c81] flex items-center justify-center gap-2 " + (hasResults ? "text-2xl" : "text-4xl");

    return (
      <div className="flex h-screen bg-[#f8fafc] font-sans text-left relative">
        <div className="w-64 bg-white border-r p-6 flex flex-col shadow-sm z-10">
          <div className="flex items-center gap-2 text-blue-600 font-bold mb-10 text-xl italic"><Activity /> ADR PRO</div>
          <button onClick={() => setView('overview')} className="flex items-center gap-3 p-4 text-slate-400 hover:bg-slate-50 rounded-2xl font-bold w-full mb-4 transition-all">
            <Users size={18} /> 病人總覽
          </button>
          <button className="flex items-center gap-3 p-4 bg-blue-600 text-white rounded-2xl font-bold w-full shadow-lg">
            <Pill size={18} /> 藥物查詢
          </button>
        </div>

        <div className="flex-1 overflow-y-auto relative">
          <div className={repoContainerClass}>
            <div className={logoContainerClass}>
              <h1 className={logoTextClass}>
                <Building2 className="text-[#0f4c81]" size={hasResults ? 28 : 40} /> 
                台北榮總藥物查詢
              </h1>
              {!hasResults && <p className="text-slate-500 text-lg mt-3 font-bold tracking-widest">臨床醫師專用搜尋引擎</p>}
            </div>

            <div className="w-full max-w-2xl px-6">
              <div className="flex items-center bg-white border border-slate-200 rounded-full px-6 py-3 shadow-lg hover:shadow-xl transition-shadow">
                <Search className="text-slate-400 mr-3 cursor-pointer" size={22} onClick={handleTextSearch} />
                <input 
                  type="text"
                  value={searchQuery}
                  onChange={(e) => setSearchQuery(e.target.value)}
                  onKeyDown={(e) => { if (e.key === 'Enter') handleTextSearch(); }}
                  className="flex-1 outline-none text-xl text-slate-800 bg-transparent"
                  placeholder="輸入藥名 (支援自動完成)..."
                />
                {searchQuery && (
                  <X className="text-slate-400 cursor-pointer ml-3 hover:text-slate-600" size={24} onClick={() => {
                    setSearchQuery(''); setHasResults(false); setSearchResults([]);
                  }} />
                )}
              </div>
            </div>

            <div className="flex flex-wrap justify-center gap-4 mt-8 px-6 font-bold text-sm">
              <button onClick={handleSearchAll} className="flex items-center gap-2 px-5 py-2 rounded-full border border-[#0f4c81] text-[#0f4c81] hover:bg-[#0f4c81] hover:text-white transition-colors bg-white shadow-sm">
                <Database size={18} /> 收錄藥物
                <span className="bg-[#0f4c81] text-white px-2 py-0.5 rounded-full text-xs ml-1">{stats.total || '-'}</span>
              </button>
              <button onClick={handleSearchReactions} className="flex items-center gap-2 px-5 py-2 rounded-full border border-rose-600 text-rose-600 hover:bg-rose-600 hover:text-white transition-colors bg-white shadow-sm">
                <AlertTriangle size={18} /> 不良反應藥物
                <span className="bg-rose-600 text-white px-2 py-0.5 rounded-full text-xs ml-1">{stats.with_reactions || '-'}</span>
              </button>
              <button onClick={() => setShowCategories(!showCategories)} className="flex items-center gap-2 px-5 py-2 rounded-full border border-emerald-600 text-emerald-600 hover:bg-emerald-600 hover:text-white transition-colors bg-white shadow-sm">
                <HeartPulse size={18} /> 身體反應分類
                <ChevronDown size={16} className={"transition-transform " + (showCategories ? "rotate-180" : "")} />
              </button>
            </div>

            {showCategories && (
              <div className="mt-6 p-6 bg-white rounded-2xl border border-slate-200 shadow-sm max-w-4xl w-full mx-6 text-center">
                 <h6 className="text-slate-500 mb-4 font-bold">請選擇受影響的身體系統進行過濾：</h6>
                 <div className="flex flex-wrap justify-center gap-2">
                   {categories.map(sys => (
                     <span 
                       key={sys} 
                       onClick={() => handleCategoryClick(sys)}
                       className={"px-4 py-1.5 border rounded-full text-sm font-bold cursor-pointer transition-all hover:shadow-sm " + (selectedCategory === sys ? "bg-emerald-600 text-white border-emerald-600" : "bg-white text-slate-600 hover:border-emerald-400")}
                     >
                       {sys}
                     </span>
                   ))}
                 </div>
              </div>
            )}
          </div>

          {hasResults && (
            <div className="max-w-5xl mx-auto p-8 fade-in">
              <div className="flex justify-between items-center border-b pb-4 mb-6">
                <div className="text-xl font-bold text-slate-800">
                  顯示 <strong>{currentLabel}</strong>，共 <strong>{searchResults.length}</strong> 筆結果
                </div>
                <div className="flex items-center gap-4 text-sm font-bold text-slate-500">
                  <span className="bg-white border px-3 py-1 rounded-full shadow-sm">資料庫: 2024.11</span>
                </div>
              </div>

              {isLoading ? (
                <div className="flex flex-col items-center justify-center py-20 text-slate-400">
                  <Loader2 className="animate-spin mb-4 text-blue-500" size={40} />
                  <p className="font-bold text-lg">正在從資料庫撈取資料...</p>
                </div>
              ) : searchResults.length > 0 ? (
                <div className="bg-white border rounded-2xl overflow-hidden shadow-sm">
                  <table className="w-full text-left">
                    <thead className="bg-slate-50 text-slate-500 text-sm border-b">
                      <tr>
                        <th className="p-5 font-bold w-32 text-center">藥碼</th>
                        <th className="p-5 font-bold">藥物名稱 (Drug Name)</th>
                        <th className="p-5 font-bold text-right">狀態</th>
                      </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-100">
                      {searchResults.map((drug, i) => {
                        const rawReaction = String(drug.adverse_reaction || '').toLowerCase();
                        const hasReaction = rawReaction !== 'nan' && rawReaction !== '';

                        return (
                          <tr key={i} className={"transition-colors cursor-pointer group hover:bg-blue-50 " + (!hasReaction ? "bg-slate-50/50" : "bg-white")} onClick={() => setSelectedDrug(drug)}>
                            <td className="p-5 font-mono text-slate-500 font-bold text-center">{drug.drug_id || drug.id || "-"}</td>
                            <td className="p-5">
                              <div className="font-black text-[#0f4c81] text-lg">{drug.name}</div>
                              {selectedCategory && hasReaction && (
                                <div className="text-xs text-emerald-600 font-bold mt-1 bg-emerald-50 inline-block px-2 py-0.5 rounded border border-emerald-100">不良反應涉及: {selectedCategory}</div>
                              )}
                            </td>
                            <td className="p-5 text-right">
                              {hasReaction ? (
                                <span className="bg-rose-50 text-rose-600 px-4 py-1.5 rounded-full text-xs font-black tracking-widest border border-rose-200 shadow-sm inline-flex items-center gap-1">
                                  <AlertTriangle size={12}/> 注意不良反應
                                </span>
                              ) : (
                                <span className="bg-amber-50 text-amber-700 px-4 py-1.5 rounded-full text-xs font-black tracking-widest border border-amber-200 shadow-sm inline-flex items-center gap-1">
                                  <ClipboardCheck size={12}/> 人工待確認
                                </span>
                              )}
                            </td>
                          </tr>
                        );
                      })}
                    </tbody>
                  </table>
                </div>
              ) : (
                <div className="text-center py-20 text-slate-400 font-bold text-xl bg-white rounded-2xl border shadow-sm">
                  找不到符合的結果
                </div>
              )}
            </div>
          )}
        </div>

        {selectedDrug && (
          <div className="fixed inset-0 bg-slate-900/40 backdrop-blur-sm z-[100] flex items-center justify-center p-4 fade-in" onClick={() => setSelectedDrug(null)}>
            <div className="bg-white rounded-3xl w-full max-w-2xl shadow-2xl overflow-hidden" onClick={e => e.stopPropagation()}>
              <div className="p-6 border-b flex justify-between items-center bg-slate-50">
                <div className="flex items-center gap-3">
                  <div className="bg-[#0f4c81] text-white px-3 py-1 rounded font-mono font-bold text-sm">{selectedDrug.drug_id || selectedDrug.id || "N/A"}</div>
                  <h2 className="text-2xl font-black text-[#0f4c81] italic tracking-tight">{selectedDrug.name}</h2>
                </div>
                <button onClick={() => setSelectedDrug(null)} className="p-2 hover:bg-slate-200 rounded-full transition-colors"><X size={24} className="text-slate-500"/></button>
              </div>
              <div className="p-8 max-h-[60vh] overflow-y-auto">
                <div className="mb-6">
                  <h3 className="text-sm font-bold text-slate-400 uppercase tracking-widest mb-2 flex items-center gap-2"><HeartPulse size={16}/> 紀錄的不良反應</h3>
                  <div className="p-4 bg-rose-50 border border-rose-100 rounded-xl text-rose-900 font-medium leading-relaxed">
                    {String(selectedDrug.adverse_reaction || '').toLowerCase() === 'nan' || !selectedDrug.adverse_reaction 
                      ? "目前資料庫無特別標註不良反應，或需人工確認。" 
                      : selectedDrug.adverse_reaction}
                  </div>
                </div>
              </div>
              <div className="p-6 border-t bg-slate-50 text-right">
                <button onClick={() => setSelectedDrug(null)} className="bg-[#0f4c81] text-white px-8 py-2.5 rounded-xl font-bold hover:bg-blue-800 transition-colors shadow-md">關閉視窗</button>
              </div>
            </div>
          </div>
        )}
      </div>
    );
  }

  // --- 2. 臨床儀表板 (Dashboard) 視圖 ---
  if (view === 'dashboard') {
    return (
      <div className="flex h-screen bg-[#F8FAFC] font-sans text-left">
        <div className="w-64 bg-white border-r p-6 flex flex-col shadow-sm">
          <div className="flex items-center gap-2 text-blue-600 font-bold mb-10 text-xl italic"><Activity /> ADR PRO</div>
          <button onClick={() => setView('overview')} className="flex items-center gap-3 p-4 bg-blue-600 text-white rounded-2xl font-bold shadow-lg w-full mb-4 transition-all"><Users size={18} /> 病人總覽</button>
          <button onClick={() => {setView('repository'); setHasResults(false); setSearchQuery(''); setSelectedCategory('');}} className="flex items-center gap-3 p-4 text-slate-400 hover:bg-slate-50 rounded-2xl font-bold w-full transition-all"><Pill size={18} /> 藥物查詢</button>
        </div>

        <div className="flex-1 overflow-y-auto p-8">
          <div className="flex justify-between items-center mb-8">
            <div className="flex items-center gap-4">
              <button onClick={() => setView('overview')} className="p-3 bg-white border rounded-xl hover:text-blue-600 shadow-sm transition-all"><ArrowLeft size={18} /></button>
              <div className="bg-white px-6 py-3 rounded-2xl border flex items-center gap-3 shadow-sm font-bold text-slate-700 text-sm italic">
                {admissionHistory[0].date} <ChevronDown size={14} className="text-slate-300" />
              </div>
            </div>
            <div className="flex gap-2">
              {[3, 7, 14].map(d => (
                <button key={d} onClick={() => { setWindowSize(d); setStartIndex(0); }} className={windowSize === d ? "px-6 py-2 rounded-lg bg-blue-600 text-white font-bold text-xs" : "px-6 py-2 bg-white text-slate-400 border font-bold text-xs hover:bg-slate-50 transition-all"}>{d}D</button>
              ))}
            </div>
          </div>

          <div className="bg-white rounded-[2.5rem] p-10 border border-slate-100 shadow-sm mb-8">
            <div className="h-72 w-full mb-6">
              <ResponsiveContainer>
                <LineChart data={visibleData} margin={{ left: 10, right: 10 }}>
                  <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#F1F5F9" />
                  <XAxis dataKey="date" axisLine={false} tickLine={false} tick={{fill: '#94A3B8', fontSize: 11, fontWeight: 'bold'}} />
                  <YAxis yAxisId="na" domain={[120, 160]} ticks={[120, 130, 140, 150, 160]} axisLine={false} tickLine={false} tick={{fill: '#F97316', fontSize: 10, fontWeight: 'bold'}} width={40} />
                  <YAxis yAxisId="k" orientation="right" domain={[2, 8]} ticks={[2, 4, 6, 8]} axisLine={false} tickLine={false} tick={{fill: '#6366F1', fontSize: 10, fontWeight: 'bold'}} width={40} />
                  <Tooltip contentStyle={{ borderRadius: '15px', border: 'none', boxShadow: '0 10px 20px rgba(0,0,0,0.05)', fontWeight: 'bold' }} />

                  <ReferenceArea yAxisId="na" y1={135} y2={145} fill="#F97316" fillOpacity={0.05}>
                    <Label value="Na Range (135-145)" position="insideTopLeft" fill="#F97316" fontSize={10} fontWeight="bold" />
                  </ReferenceArea>
                  <ReferenceArea yAxisId="k" y1={3.5} y2={5.0} fill="#6366F1" fillOpacity={0.05}>
                    <Label value="K Range (3.5-5.0)" position="insideBottomRight" fill="#6366F1" fontSize={10} fontWeight="bold" />
                  </ReferenceArea>

                  <Line yAxisId="na" type="monotone" dataKey="na" stroke="#F97316" strokeWidth={5} dot={{r: 6, fill: '#F97316', strokeWidth: 3, stroke: '#fff'}} isAnimationActive={false} />
                  <Line yAxisId="k" type="monotone" dataKey="k" stroke="#6366F1" strokeWidth={5} dot={{r: 6, fill: '#6366F1', strokeWidth: 3, stroke: '#fff'}} isAnimationActive={false} />
                </LineChart>
              </ResponsiveContainer>
            </div>

            <div className="px-10 mb-12">
              <input type="range" min="0" max={21 - windowSize} value={startIndex} onChange={(e) => setStartIndex(parseInt(e.target.value))} className="w-full h-2 bg-slate-100 rounded-lg appearance-none cursor-pointer accent-blue-600" />
            </div>
          </div>
        </div>
      </div>
    );
  }

  // --- 3. 病人總覽 (Overview) 視圖 ---
  return (
    <div className="flex h-screen bg-[#F8FAFC] font-sans text-left">
      <div className="w-64 bg-white border-r p-6 flex flex-col shadow-sm">
        <div className="flex items-center gap-2 text-blue-600 font-bold mb-10 text-xl italic tracking-tighter"><Activity strokeWidth={3}/> ADR PRO</div>
        <button className="flex items-center gap-3 p-4 bg-blue-600 text-white rounded-2xl font-bold shadow-lg shadow-blue-100 mb-4 transition-all"><Users size={18} /> 病人總覽</button>
        <button onClick={() => {setView('repository'); setHasResults(false); setSearchQuery(''); setSelectedCategory(''); setSearchResults([]);}} className="flex items-center gap-3 p-4 text-slate-400 hover:bg-slate-50 rounded-2xl font-bold transition-all"><Pill size={18} /> 藥物查詢</button>
      </div>

      <div className="flex-1 p-12 overflow-y-auto">
        <h1 className="text-2xl font-black italic text-slate-800 mb-8 border-b-[3px] border-blue-600 inline-block pb-1 uppercase tracking-tight">Patient Admission Records</h1>
        <div className="bg-white rounded-2xl shadow-sm border border-slate-100 overflow-hidden max-w-6xl">
          <table className="w-full text-left">
            <thead className="bg-white border-b border-slate-100 text-slate-400 text-[11px] font-bold uppercase tracking-widest">
              <tr><th className="py-6 px-8">病歷 ID</th><th className="py-6 px-8">病患</th><th className="py-6 px-8 text-center">目前房號</th><th className="py-6 px-8 text-center">最新 Na+ / K+</th><th className="py-6 px-8 text-right pr-12">監測狀態</th></tr>
            </thead>
            <tbody className="divide-y divide-slate-50">
              {mockPatients.map(p => (
                <tr key={p.id} onClick={() => { setSelectedPatient(p); setView('dashboard'); }} className="hover:bg-slate-50 transition-all cursor-pointer group">
                  <td className="py-6 px-8 font-black text-blue-600 text-sm tracking-tight">{p.id}</td>
                  <td className="py-6 px-8 text-slate-700 font-bold text-sm">{p.name} <span className="text-slate-400 font-normal ml-1">{p.info}</span></td>
                  <td className="py-6 px-8 text-slate-500 font-medium text-sm text-center">{p.room}</td>
                  <td className="py-6 px-8 font-sans font-bold text-base text-center">
                    <span className={p.status === '危急' ? "text-rose-500 underline decoration-rose-500 underline-offset-4 font-black" : "text-slate-700 font-black"}>{p.na}</span> 
                    <span className="text-slate-400 font-normal mx-1">/</span> 
                    <span className="text-slate-700 font-black">{p.k}</span>
                  </td>
                  <td className="py-6 px-8 text-right pr-12">
                    <span className={p.status === '危急' ? "bg-rose-100 text-rose-500 px-4 py-1.5 rounded-full text-[11px] font-bold tracking-widest border border-rose-50" : "bg-[#FEF3C7] text-[#D97706] px-4 py-1.5 rounded-full text-[11px] font-bold tracking-widest border border-yellow-50"}>{p.status}</span>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
}
